// SD card preset images — real FAT12 volumes, not sketches of one.
//
// Generated by devices/tools/make_sd_images.py, which builds each image,
// parses it back the way a driver would, and only then writes this file.
// Do not edit by hand; edit the generator and re-run it.
//
// The images are stored as the runs of bytes that are not zero, because a
// formatted volume is mostly zeros: 4 KB of image costs a few hundred
// bytes of source here. UnitSdCardModel::loadImage expands them.
#pragma once

#include <stddef.h>
#include <stdint.h>

namespace ebsd {

// One stretch of non-zero bytes at a byte offset into the whole volume.
struct ImageRun {
  uint32_t offset;
  uint16_t length;
  const uint8_t* bytes;
};

// A whole card image. Everything not covered by a run is zero.
struct Image {
  const char* name;
  uint32_t blocks;
  const ImageRun* runs;
  size_t runCount;
};

// A FAT12 volume holding one file, HELLO.TXT.
// 8 blocks, 126 non-zero bytes in 6 runs.
extern const Image kFat12Hello;

// A formatted FAT12 volume with no files on it.
// 8 blocks, 58 non-zero bytes in 3 runs.
extern const Image kFat12Empty;

// The boot signature erased, so a driver refuses on its first
// check. The easy corruption.
// 8 blocks, 87 non-zero bytes in 6 runs.
extern const Image kFat12BadBoot;

// The cluster chain loops back on itself (2 -> 3 -> 2). A reader
// that follows it without a guard never finishes.
// 8 blocks, 105 non-zero bytes in 6 runs.
extern const Image kFat12Circular;

// The chain leads to a cluster past the end of the volume, so the
// next block a reader asks for does not exist.
// 8 blocks, 104 non-zero bytes in 6 runs.
extern const Image kFat12OutOfRange;

// The directory claims four clusters; the chain ends after one, so
// a reader trusting the size runs off the file.
// 8 blocks, 105 non-zero bytes in 6 runs.
extern const Image kFat12SizeMismatch;

// Bytes-per-sector is zero. The boot signature is intact, so this
// gets past the easy check and into the arithmetic.
// 8 blocks, 104 non-zero bytes in 6 runs.
extern const Image kFat12ZeroBps;

}  // namespace ebsd
